    ctx.strokeStyle='#8A8F99'; ctx.lineWidth=6; ctx.lineCap='round'; ctx.beginPath(); ctx.moveTo(x+cardW-70,y-20); ctx.lineTo(x+cardW-70,y+70); ctx.arc(x+cardW-56,y+70,14,Math.PI,0); ctx.lineTo(x+cardW-42,y+10); ctx.stroke();
