  const bark=(t0)=>{ tone(t0,320,200,0.12,'sawtooth',0.14,0.005,0.06); noise(t0,0.1,'bandpass',900,600,0.1,0.005,0.06); };
  const whistle=(t0)=>{ for(let k=0;k<6;k++) tone(t0+k*0.05,2200+(k%2)*300,2200+(k%2)*300,0.05,'square',0.06,0.003,0.02); };
  tack(0.6); tack(1.3); tack(2.0); bell(3.0,2093,0.3); noise(3.1,0.4,'lowpass',200,120,0.3,0.05,0.3);                          /* Schreibmaschine, Ding, Motor startet */
  bed('lowpass',95,0.8,[[3.0,0],[3.6,0.13],[10.6,0.13],[11.0,0.04],[13.8,0.04],[14.4,0.16],[17.6,0.16],[18.1,0.02],[24,0.02]],8,0.05);   /* Motor */
  bed('bandpass',300,1.5,[[3.4,0],[4,0.03],[10.4,0.03],[10.8,0],[14.0,0],[14.6,0.05],[17.4,0.05],[17.8,0]],0,0);                    /* Reifen */
  { const r=S.rng(3); for(let k=0;k<14;k++) noise(3.5+r()*6.5,0.06,'bandpass',800,800,0.08,0.005,0.04,2); }                          /* Schnueffel schnuppert */
  tone(7.0,700,560,0.25,'sine',0.1,0.02,0.15); tone(7.3,560,700,0.25,'sine',0.1,0.02,0.15); { const r=S.rng(5); for(let k=0;k<8;k++) noise(6.9+r()*4,0.12,'bandpass',400,900,0.06,0.03,0.08); }   /* Eulalia: Huhu, Fluegel */
