  /* Code knacken */ for(let k=0;k<8;k++) tack(17.85+k*0.07); tone(18.4,120,60,0.35,'sine',0.5,0.002,0.25); noise(18.4,0.2,'lowpass',400,200,0.4,0.002,0.15); tone(18.5,180,140,0.35,'sawtooth',0.06,0.02,0.2); [18.7,18.85,19.0].forEach((t,k)=>bell(t,[1568,1976,2349][k],0.24)); { const r=S.rng(9); for(let k=0;k<8;k++){ const f=2400+r()*1800; tone(18.7+r()*0.7,f,f,0.12,'sine',0.06,0.005,0.1); } }
